import random
import struct
from typing import List

# Data type: byte buffer with at least one occurrence of two consecutive NUL bytes ("\0\0")
# Goal: Generate valid buffers likely exercising different code paths for doublenul(buf, len)
# Strategy:
# - Produce a variety of double-NUL encodings:
#   * At beginning, middle, end
#   * Multiple double-NULs
#   * Embedded NUL-separated strings (e.g., "a\0b\0\0")
#   * Long segments, empty segments, repeated separators
# - Keep size <= 4096 bytes
# - Always ensure at least one "\0\0" within the reported length

MAX_SIZE = 4096

def _rand_ascii(r: random.Random, min_len: int, max_len: int) -> bytes:
    n = r.randint(min_len, max_len)
    # Avoid NUL in these segments; doublenul semantics typically expect NUL as separator
    alphabet = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_.:/\\[]{}(),+@% "
    return bytes(r.choice(alphabet) for _ in range(n))

def _make_list(r: random.Random, count_range=(0, 10), part_len=(0, 64)) -> List[bytes]:
    cnt = r.randint(*count_range)
    parts = []
    for _ in range(cnt):
        parts.append(_rand_ascii(r, part_len[0], part_len[1]))
    return parts

def _place_double_nul(r: random.Random, base: bytearray) -> None:
    # Ensure at least one double NUL exists; place it at a random valid index
    if len(base) < 2:
        base.extend(b"X" * (2 - len(base)))
    idx = r.randint(0, len(base) - 2)
    base[idx] = 0
    base[idx + 1] = 0

def _gen_case_begin_double_nul(r: random.Random) -> bytes:
    payload = bytearray()
    payload += b"\0\0"
    payload += _rand_ascii(r, 0, 64)
    return bytes(payload)

def _gen_case_end_double_nul(r: random.Random) -> bytes:
    payload = bytearray()
    payload += _rand_ascii(r, 0, 64)
    payload += b"\0\0"
    return bytes(payload)

def _gen_case_middle_double_nul(r: random.Random) -> bytes:
    left = _rand_ascii(r, 0, 128)
    right = _rand_ascii(r, 0, 128)
    return left + b"\0\0" + right

def _gen_case_multi_lists(r: random.Random) -> bytes:
    # Build NUL-separated list ending with double NUL, possibly multiple groups
    buf = bytearray()
    groups = r.randint(1, 4)
    for g in range(groups):
        parts = _make_list(r, (1, 8), (0, 32))
        for p in parts:
            buf += p + b"\0"
        buf += b"\0"  # list terminator -> introduces at least one double NUL between last item NUL and terminator NUL
        # Optionally pad between groups with printable bytes to vary positions
        if g != groups - 1 and r.random() < 0.5:
            buf += _rand_ascii(r, 0, 16)
    return bytes(buf)

def _gen_case_sparse_zeroes(r: random.Random) -> bytes:
    # Create buffer with random bytes and insert multiple zero runs of varying length
    total = r.randint(8, 512)
    buf = bytearray(_rand_ascii(r, total // 2, total // 2))
    # sprinkle bytes to reach target size
    while len(buf) < total:
        if r.random() < 0.2:
            # insert a zero run (length 1..4)
            run = r.randint(1, 4)
            buf += b"\0" * run
        else:
            buf += _rand_ascii(r, 1, 8)
        if len(buf) > total:
            buf = buf[:total]
            break
    # Guarantee at least one double NUL
    _place_double_nul(r, buf)
    return bytes(buf)

def _gen_case_exact_minimum(r: random.Random) -> bytes:
    # Minimum meaningful sizes around 2..8 bytes
    choices = [b"\0\0", b"A\0\0", b"\0\0A", b"AB\0\0", b"\0\0AB", b"A\0\0B"]
    return r.choice(choices)

def _gen_case_large_list(r: random.Random) -> bytes:
    # Create a larger but bounded list of entries, totaling <= MAX_SIZE
    buf = bytearray()
    while len(buf) < MAX_SIZE - 2:
        part = _rand_ascii(r, 0, 64)
        if len(buf) + len(part) + 2 > MAX_SIZE:
            break
        buf += part + b"\0"
        if r.random() < 0.05:
            break
    buf += b"\0"
    return bytes(buf)

def _gen_case_repeated_double_nul(r: random.Random) -> bytes:
    # Sequence of multiple consecutive double-NULs separated by data
    buf = bytearray()
    segments = r.randint(1, 6)
    for i in range(segments):
        buf += _rand_ascii(r, 0, 32)
        buf += b"\0\0"
    buf += _rand_ascii(r, 0, 32)
    return bytes(buf)

def _gen_case_unicode_like(r: random.Random) -> bytes:
    # Compose UTF-8-like segments separated by NUL, then terminate with extra NUL
    def rand_utf8_bytes() -> bytes:
        choice = r.random()
        if choice < 0.5:
            return bytes([r.randint(0x20, 0x7E)])  # ASCII printable
        elif choice < 0.75:
            # 2-byte sequence
            cp = r.randint(0x80, 0x7FF)
        elif choice < 0.95:
            cp = r.randint(0x800, 0xFFFF)
        else:
            cp = r.randint(0x10000, 0x10FFFF)
        try:
            return chr(cp).encode('utf-8')
        except Exception:
            return b"?"
    buf = bytearray()
    entries = r.randint(1, 16)
    for _ in range(entries):
        size = r.randint(0, 24)
        part = bytearray()
        for _ in range(size):
            part += rand_utf8_bytes()
            if len(part) > 64:
                break
        buf += bytes(part) + b"\0"
    buf += b"\0"
    if len(buf) > MAX_SIZE:
        buf = buf[:MAX_SIZE]
        # Ensure trailing has at least one double NUL; enforce at the end if we cut
        if not buf.endswith(b"\0\0"):
            # Make room for two NULs
            if len(buf) >= 2:
                buf[-2:] = b"\0\0"
            else:
                buf.extend(b"\0\0")
                if len(buf) > MAX_SIZE:
                    buf[:] = buf[:MAX_SIZE]
    return bytes(buf)

_CASES = [
    _gen_case_begin_double_nul,
    _gen_case_end_double_nul,
    _gen_case_middle_double_nul,
    _gen_case_multi_lists,
    _gen_case_sparse_zeroes,
    _gen_case_exact_minimum,
    _gen_case_large_list,
    _gen_case_repeated_double_nul,
    _gen_case_unicode_like,
]

def _finalize(buf: bytes, r: random.Random) -> bytes:
    # Ensure size bounds and presence of at least one double NUL
    b = bytearray(buf[:MAX_SIZE])
    if len(b) < 2:
        b.extend(b"X" * (2 - len(b)))
    if b.find(b"\0\0") == -1:
        _place_double_nul(r, b)
    # Optionally pad to random length <= 4096 to vary interaction
    if r.random() < 0.5 and len(b) < MAX_SIZE:
        pad_len = r.randint(0, min(64, MAX_SIZE - len(b)))
        # Mostly printable, sometimes zeros to create additional double-NULs
        if r.random() < 0.2:
            pad = bytearray(_rand_ascii(r, 0, max(0, pad_len - 2)))
            if len(pad) <= pad_len - 2:
                pad += b"\0\0"
            b += pad[:pad_len]
        else:
            b += _rand_ascii(r, 0, pad_len)
    # Keep within bounds
    return bytes(b[:MAX_SIZE])

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Choose a case with weighted probabilities to cover lists more often
    weights = [
        1.0,  # begin
        1.0,  # end
        1.0,  # middle
        2.0,  # multi_lists
        1.5,  # sparse_zeroes
        0.5,  # exact_minimum
        1.5,  # large_list
        1.0,  # repeated_double_nul
        1.5,  # unicode_like
    ]
    case = r.choices(_CASES, weights=weights, k=1)[0]
    buf = case(r)
    return _finalize(buf, r)
